SELECT CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, CASE WHEN customers.country IN ('JP', 'UK') THEN 'tier_1' ELSE 'other' END AS country_group, COUNT(CASE WHEN subscriptions.status = 'ACTIVE' THEN 1 END) AS active_count, MAX(subscriptions.monthly_fee) - MIN(subscriptions.monthly_fee) AS monthly_fee_range FROM subscriptions INNER JOIN customers ON subscriptions.customer_id = customers.id GROUP BY CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN customers.country IN ('JP', 'UK') THEN 'tier_1' ELSE 'other' END ORDER BY signup_cohort
